function parse_nested_parens(paren_string: string): number[] {
    const result: number[] = [];
    let currentLevel = 0;
    let maxLevel = 0;

    for (const char of paren_string) {
        if (char === '(') {
            currentLevel++;
            if (currentLevel > maxLevel) {
                maxLevel = currentLevel;
            }
        } else if (char === ')') {
            currentLevel--;
        }
    }

    result.push(maxLevel);
    return result;
}

