function make_palindrome(string: string): string {
    if (string.length === 0) return "";

    // Find the longest postfix of the string that is a palindrome
    let longestPostfix = "";
    for (let i = string.length - 1; i >= 0; i--) {
        if (isPalindrome(string.substring(i))) {
            longestPostfix = string.substring(i);
            break;
        }
    }

    // Reverse the prefix that comes before the longest postfix
    const prefix = string.substring(0, longestPostfix.length);
    const reversedPrefix = prefix.split('').reverse().join('');

    // Append the reversed prefix to the end of the string
    return string + reversedPrefix;
}

function isPalindrome(s: string): boolean {
    let left = 0;
    let right = s.length - 1;
    while (left < right) {
        if (s[left] !== s[right]) {
            return false;
        }
        left++;
        right--;
    }
    return true;
}
