function largest_prime_factor(n: number): number {
    if (n <= 1) return 0; // No prime factors for numbers less than or equal to 1

    let maxPrime = -1;

    // Divide n by 2 to remove all even factors
    while (n % 2 === 0) {
        maxPrime = 2;
        n /= 2;
    }

    // Check for odd factors from 3 onwards
    for (let i = 3; i * i <= n; i += 2) {
        while (n % i === 0) {
            maxPrime = i;
            n /= i;
        }
    }

    // If n is still greater than 2, then it is a prime number
    if (n > 2) {
        maxPrime = n;
    }

    return maxPrime;
}
