function will_it_fly(q: number[], w: number): boolean {
    // Check if the array is balanced
    const isBalanced = (arr: number[]): boolean => {
        let balance = 0;
        for (let i = 0; i < arr.length / 2; i++) {
            if (arr[i] !== arr[arr.length - 1 - i]) {
                return false;
            }
            balance += arr[i];
        }
        return balance === 0;
    };

    // Calculate the sum of the array elements
    const sum = q.reduce((acc, val) => acc + val, 0);

    // Check if the array is balanced and the sum is within the weight limit
    return isBalanced(q) && sum <= w;
}
