function starts_one_ends(n: number): number {
    if (n === 1) {
        return 1; // Only the number 1 itself is a valid n-digit number starting or ending with 1
    }
    // For n > 1, we need to consider numbers that start or end with 1
    // There are 2 * 9^(n-2) possibilities for numbers that start with 1
    // There are 2 * 9^(n-2) possibilities for numbers that end with 1
    // Subtract the overlap (numbers that both start and end with 1)
    const overlap = 2 * 9 ** (n - 2);
    return 2 * 9 ** (n - 2) - overlap;
}
