function encode(message: string): string {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    let encodedMessage = '';

    for (let char of message) {
        if (vowels.has(char)) {
            // Find the next vowel in the alphabet
            let nextVowelIndex = vowels.size - 1;
            while (nextVowelIndex >= 0 && vowels.has(message[nextVowelIndex])) {
                nextVowelIndex--;
            }
            // Replace the vowel with the next vowel in the alphabet
            encodedMessage += message[nextVowelIndex];
        } else {
            // Swap case
            encodedMessage += char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
        }
    }

    return encodedMessage;
}

