function minPath(grid: number[][], k: number): number[] {
    const N = grid.length;
    const directions = [
        [0, 1], // right
        [1, 0], // down
        [0, -1], // left
        [-1, 0] // up
    ];

    let minPath = Infinity;
    let currentPath = [];

    function dfs(x: number, y: number, path: number[]): void {
        if (path.length === k) {
            if (minPath > path.reduce((acc, curr) => acc + curr, 0)) {
                minPath = path.reduce((acc, curr) => acc + curr, 0);
                currentPath = [...path];
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N) {
                dfs(nx, ny, [...path, grid[nx][ny]]);
            }
        }
    }

    dfs(0, 0, []);
    return currentPath;
}
